mapper.select:
select
/*待接收*/
(select count(1) from survey_risk_case_info s left join survey_investigator_case sic on sic.survey_info_id = s.id
where s.delete_flag = 0  and sic.delete_flag = 0 and sic.survey_state = 0

        and sic.survey_user_id = #{surveyUserId,jdbcType=BIGINT}


        and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

) as basNotReceive,
/*调查中*/
(select count(1) from survey_risk_case_info s left join survey_investigator_case sic on sic.survey_info_id = s.id
where s.delete_flag = 0 and sic.delete_flag = 0 and sic.survey_state = 1

        and sic.survey_user_id = #{surveyUserId,jdbcType=BIGINT}


        and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

) as basSurveying,

/*初审中*/
(select count(1) from survey_risk_case_info s
    left join survey_investigator_case sic on sic.survey_info_id = s.id
    left join survey_assign_org ao on ao.survey_info_id = s.id
where s.delete_flag = 0  and sic.delete_flag = 0 and ao.delete_flag = 0 and ao.org_survey_state = 2

        and sic.survey_user_id = #{surveyUserId,jdbcType=BIGINT}


        and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

) as basOrgReviewing,

/*平台待终审*/
(select count(1) from survey_risk_case_info s left join survey_investigator_case sic on sic.survey_info_id = s.id
where s.delete_flag = 0 and s.survey_state in (22,30) and sic.delete_flag = 0

        and sic.survey_user_id = #{surveyUserId,jdbcType=BIGINT}


        and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

)as basLefanApv,

/*已调查*/
(select count(1) from survey_risk_case_info s left join survey_investigator_case sic on sic.survey_info_id = s.id
where s.delete_flag = 0  and sic.delete_flag = 0 and !(sic.survey_state in (0,1) or (sic.is_direction_success = 0))

        and sic.survey_user_id = #{surveyUserId,jdbcType=BIGINT}


        and s.entrust_org_id = #{entrustOrgId,jdbcType=BIGINT}

)as basSurveyed

from dual

select min(report_date) as minReportDate from survey_investigator_user_report
where survey_user_id = #{surveyUserId,jdbcType=BIGINT} and consignor_org_id = #{entrustOrgId,jdbcType=BIGINT}
and check_type = #{checkType,jdbcType=BIGINT}

select max(report_date) as maxReportDate from survey_investigator_user_report
where survey_user_id = #{surveyUserId,jdbcType=BIGINT} and consignor_org_id = #{entrustOrgId,jdbcType=BIGINT}
and check_type = #{checkType,jdbcType=BIGINT}
